function minimumOperationsToMakeEqual(x, y) {
  if (x <= y) {
    return y - x;
  }
  const limit = x + (x - y);
  const dist = new Array(limit + 1).fill(-1);
  dist[x] = 0;
  const queue = [x];
  for (let head = 0; head < queue.length; head++) {
    const value = queue[head];
    if (value === y) {
      return dist[value];
    }
    const neighbors = [value - 1, value + 1];
    if (value % 11 === 0) {
      neighbors.push(value / 11);
    }
    if (value % 5 === 0) {
      neighbors.push(value / 5);
    }
    for (const next of neighbors) {
      if (next >= 1 && next <= limit && dist[next] === -1) {
        dist[next] = dist[value] + 1;
        queue.push(next);
      }
    }
  }
  return dist[y];
}

