function minimumOperationsToMakeEqual(x, y) {
  // Relax "operations left to reach y" over a generous range until nothing improves,
  // sweeping upwards and then downwards so improvements spread in both directions.
  const top = 2 * Math.max(x, y) + 22;
  const left = new Array(top + 2).fill(Infinity);
  left[y] = 0;
  const relax = v => {
    let bestHere = left[v];
    if (v > 1) bestHere = Math.min(bestHere, left[v - 1] + 1);
    bestHere = Math.min(bestHere, left[v + 1] + 1);
    if (v % 11 === 0) bestHere = Math.min(bestHere, left[v / 11] + 1);
    if (v % 5 === 0) bestHere = Math.min(bestHere, left[v / 5] + 1);
    if (bestHere < left[v]) { left[v] = bestHere; return true; }
    return false;
  };
  let changed = true;
  while (changed) {
    changed = false;
    for (let v = 1; v <= top; v++) if (relax(v)) changed = true;
    for (let v = top; v >= 1; v--) if (relax(v)) changed = true;
  }
  return left[x];
}

