function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const top = size === 'small' ? (rand() < 0.5 ? 30 : 200) : 10000;
  let x = int(1, top);
  let y = int(1, top);
  if (rand() < 0.75 && x < y) [x, y] = [y, x];
  if (size === 'large' && rand() < 0.5) y = int(1, 60);
  return [x, y];
}
